function validate([score]) {
  if (!Array.isArray(score) || score.length < 1 || score.length > 10000) return 'score needs 1 to 10^4 values.';
  if (score.some(v => !Number.isInteger(v) || v < 0 || v > 1000000)) return 'Each score is an integer from 0 to 10^6.';
  if (new Set(score).size !== score.length) return 'All scores must be different.';
  return null;
}

