function findRelativeRanks(score) {
  const medals = ['Gold Medal', 'Silver Medal', 'Bronze Medal'];
  const order = score.map((_, i) => i);
  order.sort((a, b) => score[b] - score[a]);
  const answer = new Array(score.length);

  for (let place = 0; place < order.length; place++) {
    const athlete = order[place];
    if (place < 3) {
      answer[athlete] = medals[place];
    } else {
      answer[athlete] = String(place + 1);
    }
  }
  return answer;
}

