function findRelativeRanks(score) {
  return score.map(mine => {
    let better = 0;
    for (const other of score) if (other > mine) better++;
    if (better === 0) return 'Gold Medal';
    if (better === 1) return 'Silver Medal';
    if (better === 2) return 'Bronze Medal';
    return `${better + 1}`;
  });
}

