function generate(rand, size) {
  const n = size === 'large' ? 2000 : 1 + Math.floor(rand() * 9);
  const top = size === 'large' ? 1000000 : 3 * n + Math.floor(rand() * 10);
  const seen = new Set();
  const score = [];
  while (score.length < n) {
    const value = Math.floor(rand() * (top + 1));
    if (seen.has(value)) continue;
    seen.add(value);
    score.push(value);
  }
  return [score];
}
